 while(1)
 {
  ogs_pkbuf_t* pkbuf = ogs_pkbuf_alloc(NULL, OGS_MAX_SDU_LEN);
  pkbuf->data = array;
  pkbuf->len = sizeof(array);

  ogs_ngap_decode(&message, pkbuf);
  ogs_pkbuf_free(pkbuf);
  
  usleep(50000);
  static int count = 0;
  count ++;
  printf("count = %u\n", count);
  
  if (count >= 50000000)
   break;
 }
 return;
}
